"""Validate source fidelity, visibility, physical accounting and key effect boundaries."""
from pathlib import Path
from fractions import Fraction
import hashlib,json,re

ROOT=Path(__file__).resolve().parents[1]
GAME=ROOT.parents[1]
AUDIT=GAME/'docs/audit/2026-10-08/full-game'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    evidence=read(AUDIT/'HERBALISM_SOURCE_EVIDENCE.json');src=read(ROOT/'data/crafting/Decennium_Descent_Crafting_Bible_v4.json')
    recipes=[x for x in src['recipes'] if x['skill']=='Herbalism'];by={r['id']:r for r in recipes}
    data=read(ROOT/'data/director/herbalism_recipe_candidate_internal.json');cards=data['cards'];cb={c['recipeId']:c for c in cards}
    public=read(ROOT/'data/playtest/herbalism_recipe_candidate.json')['cards']
    guide=(ROOT/'docs/mechanics/HERBALISM_RECIPE_PLAYTEST.md').read_text(encoding='utf-8')
    private=(ROOT/'docs/director-only/HERBALISM_INTERNAL_PROCEDURES.md').read_text(encoding='utf-8')
    pmd=(ROOT/'docs/mechanics/HERBALISM_PUBLIC_RECIPE_CARDS.md').read_text(encoding='utf-8')
    imd=(ROOT/'docs/director-only/HERBALISM_INTERNAL_RECIPE_CARDS.md').read_text(encoding='utf-8')
    checks=[]
    def check(name,value):checks.append({'name':name,'pass':bool(value)})
    check('All 45 exact source identities present once',len(cards)==len(cb)==len(by)==45 and set(cb)==set(by))
    check('Original full source records equal captured evidence',recipes==evidence['recipes'])
    check('All 19 protected source and prior-rule artifacts unchanged',all(sha(GAME/p)==h for p,h in read(AUDIT/'HERBALISM_REVIEW_BASELINE.json')['files'].items()))
    check('Current V4 hash and source indices exact',data['sourceSha256']==evidence['sourceSha256']==sha(ROOT/'data/crafting/Decennium_Descent_Crafting_Bible_v4.json') and all(src['recipes'][c['sourceRecipeIndex']]==by[c['recipeId']] for c in cards))
    check('29 public cards exactly match public source set',len(public)==29 and {c['recipeId'] for c in public}=={r['id'] for r in recipes if r['visibility']=='public'} and public==[c for c in cards if c['visibility']=='public'])
    check('Three restricted and 13 Director entries stay internal',sum(c['visibility']=='restricted' for c in cards)==3 and sum(c['visibility']=='director-only' for c in cards)==13 and all(c['name'] not in pmd for c in cards if c['visibility']!='public'))
    check('All 29 public V5 book effect bindings exact',len(evidence['publicBookBindings'])==29 and all(b['effectMatches'] and b['paragraphs'][1]['text']=='Effect. '+by[b['recipeId']]['effects'] for b in evidence['publicBookBindings']))
    check('Preserved names, visibility, complete effects, abbreviated mechanics and legacy fields',all(c['name']==by[c['recipeId']]['name'] and c['visibility']==by[c['recipeId']]['visibility'] and c['sourceEffect']==by[c['recipeId']]['effects'] and c['sourceMechanics']==by[c['recipeId']]['mechanics'] and c['sourceLegacyFields']=={k:by[c['recipeId']][k] for k in ['legacyName','legacyEffect'] if k in by[c['recipeId']]} for c in cards))
    check('All source requirements and component occurrences preserved',all(all(by[c['recipeId']][k]==v for k,v in c['sourceRequirements'].items()) for c in cards))
    check('Nonconsumed mortars remain reusable and excluded from consumed mass',all(c['operational']['craft']['sourceConsumedMassLb']==float(sum(Fraction(str(x['weight']))*x['quantity'] for x in by[c['recipeId']]['components'] if x['consumed'])) for c in cards) and 'Mortar and pestle' in guide and '`consumed:false`' in guide)
    check('Every dose magical nonspell without generic pool',all(c['operational']['effect']['magical'] and not c['operational']['effect']['spell'] and not c['operational']['effect']['concentration'] and not c['operational']['effect']['createsResourcePool'] for c in cards))
    check('Four exact antidote IDs have all-application removal, advantage and no numeric bonus',{c['recipeId'] for c in cards if c['operational']['effect']['kind']=='antidote'}=={'recipe-200','recipe-220','recipe-238','recipe-646'} and all(cb[f'recipe-{n}']['operational']['effect']['numericSaveBonus']==0 and cb[f'recipe-{n}']['operational']['effect']['poisonSaveAdvantage'] for n in [200,220,238,646]))
    check('Healing dice exactly preserved',all(c['operational']['effect'].get('healing')==by[c['recipeId']]['mechanics'].get('healing') for c in cards))
    check('Hazard bonus/tag exact and bounded per card',all(c['operational']['effect']['checkAndSaveBonus']==by[c['recipeId']]['mechanics']['bonus'] and c['operational']['effect']['hazardTag']==by[c['recipeId']]['mechanics']['tag'] and c['operational']['effect']['scope']['text'] in c['operational']['text'] for c in cards if c['operational']['effect']['kind']=='hazard-buff'))
    check('Fixed and rest durations individually match source prose',all((c['operational']['effect']['durationSeconds']==None and 'long rest' in by[c['recipeId']]['effects']) or (lambda m: m is not None and c['operational']['effect']['durationSeconds']==int(m[1])*(60 if m[2]=='minute' else 3600))(re.search(r'(\d+) (minute|hour)',by[c['recipeId']]['effects'])) for c in cards if c['operational']['effect']['kind'] in ['antidote','hazard-buff']))
    check('Names cannot add sleep or repeated regeneration',cb['recipe-644']['operational']['effect']['kind']=='hazard-buff' and cb['recipe-645']['operational']['effect']['healing']=='1d6+2' and 'does not induce sleep' in guide and 'no periodic regeneration' in guide)
    check('Topical timing is 60 seconds and 10 regular-turn Actions',all(c['operational']['activation']['activeMinutes']==1 and c['operational']['activation']['consecutiveRegularTurnActions']==10 and c['operational']['activation']['requiresElapsedTimeAndActions'] for c in cards if c['operational']['effect']['kind']=='topical-healing'))
    check('Local care cannot duplicate healing attempts or automatically clear Wounds',all(c['operational']['effect']['localCare']['maxSelectedRecords']==1 and not c['operational']['effect']['localCare']['duplicatesHealingEndpointAttempt'] and c['operational']['effect']['localCare']['requiresExistingMedicineRemovalDC'] and c['operational']['effect']['woundsRemoved']==0 for c in cards if c['operational']['effect']['kind']=='topical-healing'))
    check('Panacea cure count, order, independence and source exceptions explicit',cb['recipe-647']['operational']['effect']['cure']['count']==1 and cb['recipe-647']['operational']['effect']['cure']['timing']=='before healing' and cb['recipe-647']['operational']['effect']['cure']['independentOfHealing'] and not cb['recipe-647']['operational']['effect']['cure']['ignoresSourceRemovalRestrictions'])
    check('Panacea has ten-minute/100-turn application, not a reduced effect duration',cb['recipe-647']['operational']['activation']['activeMinutes']==10 and cb['recipe-647']['operational']['activation']['consecutiveRegularTurnActions']==100 and cb['recipe-647']['operational']['craft']['flawed']['mode']=='treat-as-Failed')
    check('Panacea has fixed mode, elapsed fallback, no interruption spend and one active attempt',all(cb['recipe-647']['operational']['effect']['cooldown'][k]==v for k,v in {'campaignModeLockedBeforeFirstUse':True,'fallbackSeconds':8640000,'spentOnInterruption':False,'oneConcurrentAttemptPerRecipient':True,'resetsOnDeathRestOpeningOrOwnership':False}.items()))
    check('Panacea private details not published in public manuscript','Worldroot Panacea' not in guide+pmd and 'recipe-647' not in guide+pmd and all(c['operational']['privateRules'] is None for c in public))
    check('Physical mass, glass profile and one-dose slot consistent',all(all(c['operational']['physical'][k]==v for k,v in {'compoundWeightLb':.1,'containerWeightLb':.1,'grossWeightLb':.2,'containerAC':13,'containerHP':1,'doses':1,'vialSlots':1}.items()) for c in cards))
    check('Maximum packaging reserved with no post-roll acquisition',all(c['operational']['craft']['additionalMasterworkGlassVials']==by[c['recipeId']]['quantity']*3//2 and c['operational']['craft']['packagingAndCarrierReservedBeforeCheck'] and not c['operational']['craft']['postRollAcquisitionAllowed'] for c in cards) and 'even when intending to select durability' in guide)
    check('Carrier deficit accounts for maximum legal catalyst retention',all(Fraction(str(c['operational']['craft']['minimumAvailableCompoundMassLb']))+Fraction(str(c['operational']['craft']['masterworkSupplementaryCarrierLb']))>=Fraction(c['operational']['craft']['additionalMasterworkGlassVials'],10) for c in cards))
    check('Recipe 201 is the sole carrier deficit: 0.14 lb',{c['recipeId']:c['operational']['craft']['masterworkSupplementaryCarrierLb'] for c in cards if c['operational']['craft']['masterworkSupplementaryCarrierLb']}=={'recipe-201':.14})
    check('Spent bottles do not regenerate ingredients or magical uses',all(c['operational']['physical']['postUseContainer']['magicalUsesRemaining']==0 and c['operational']['physical']['postUseContainer']['ingredientTierBenefit'] is None and not c['operational']['physical']['postUseContainer']['ingredientPropertiesRecovered'] and not c['operational']['physical']['postUseContainer']['reuseRequiresRepurchase'] for c in cards))
    check('Flawed multi-dose batches floor quantity',all(c['operational']['craft']['flawed']['mode']=='half-batch-quantity' and c['operational']['craft']['flawed']['quantity']==by[c['recipeId']]['quantity']//2 for c in cards if by[c['recipeId']]['quantity']>=2))
    check('Flawed fixed durations halve with antidote instant cure retained',all(c['operational']['craft']['flawed']['durationSeconds']==max(6,(c['operational']['effect']['durationSeconds']//12)*6) for c in cards if c['operational']['craft']['flawed']['mode']=='half-fixed-duration') and cb['recipe-220']['operational']['craft']['flawed']=={'mode':'half-fixed-duration','durationSeconds':1800,'instantCureUnchanged':True})
    check('Rest-duration and instantaneous singleton failures are explicit',all(cb[f'recipe-{n}']['operational']['craft']['flawed']['mode']=='treat-as-Failed' for n in [238,239,646,647,645,203]))
    check('Quality durability retains Standard yield and cannot buff potency',all(c['operational']['craft']['qualityDurabilityOption']=={'batchQuantity':'Standard','allFinishedContainersMaxAndCurrentHP':2,'bonusYieldCombined':False} and not c['operational']['craft']['qualityPotencyBonus'] for c in cards))
    check('Every card preserves the exact Standard batch reference and unit ratio',all(c['operational']['value']['sourceStandardBatchReferenceGp']==by[c['recipeId']]['economy']['recommendedMarketValue'] and c['operational']['value']['unitReferenceGp']=={'numerator':by[c['recipeId']]['economy']['recommendedMarketValue'],'denominator':by[c['recipeId']]['quantity']} for c in cards))
    check('Public and internal headings account for all cards exactly once',all(imd.count('## '+c['recipeId']+' — ')==1 and imd.count('**Operational effect:** '+c['operational']['text'])>=1 for c in cards) and all(pmd.count('## '+c['recipeId']+' — ')==1 and '**Operational effect:** '+c['operational']['text'] in pmd for c in public))
    check('No runtime or balance approval inferred',data['runtimeImplemented'] is False and data['balanceApproved'] is False)
    check('No automatic artisan-tool bonus, drug profile or source deletion','not an artisan-tool trade by default' in guide and 'without an actual reviewed substance profile' in guide and 'No original source has been deleted' in guide)
    check('Operational recipe tags derive only from explicit current mechanics.tag',all(c['operational']['effect']['recipeTags']==([by[c['recipeId']]['mechanics']['tag']] if 'tag' in by[c['recipeId']]['mechanics'] else []) and 'sourceTags' not in c['operational']['effect'] for c in cards))
    check('Original source tag arrays remain losslessly separate',all(c['sourceRecipeTags']==by[c['recipeId']]['tags'] for c in cards))
    check('Ten specifically flagged tag profiles are repaired',{n:cb[f'recipe-{n}']['operational']['effect']['recipeTags'] for n in [232,233,234,235,236,237,238,239,240,647]}=={232:['Acid'],233:['Lightning'],234:['Earth'],235:['Cold'],236:['Fire'],237:['Poison'],238:['Unholy'],239:['Psychic'],240:['Lightning'],647:[]})
    check('Every printed card mandates full maximum packaging reservation',pmd.count('The full Masterwork-reserve amount shown above')==29 and imd.count('The full Masterwork-reserve amount shown above')==45 and 'All chosen-output packaging' not in pmd+imd and all(c['operational']['craft']['maximumMasterworkReserveMandatory'] for c in cards))
    check('Timed procedures finish without an eleventh/101st Action',all(c['operational']['activation']['additionalActionAfterRequiredCount'] is False and c['operational']['activation']['continuousConditionsRequiredUntilResolution'] is True for c in cards if c['operational']['activation']['activeMinutes']) and 'no eleventh Action' in guide and 'no eleventh Action' in private)
    check('Bleed duplicate rule names the same and different actual record',"for that same record, including an unsuccessful source save" in guide and 'for that different record' in guide)
    check('Panacea beneficial completion projection matches approved clarification',cb['recipe-647']['operational']['effect']['cooldown']['spentOnWhollyBlockedCompletion'] is False and cb['recipe-647']['operational']['effect']['cooldown']['eligibilityRecheckedBeforeResolution'] is True and len(cb['recipe-647']['operational']['effect']['cooldown']['benefitCriteria'])==3 and cb['recipe-647']['operational']['effect']['cure']['noEligibleCureBlocksHealing'] is False)
    check('Opened dose commencement commits one continuous use','Administration must begin before it expires' in guide and 'rather than retaining a second reusable inventory dose' in guide)
    report={'status':'PASS' if all(c['pass'] for c in checks) else 'FAIL','scope':'Source, authored projection and boundary validation; not a runtime or human balance test.','checks':checks,'failed':[c['name'] for c in checks if not c['pass']]}
    (AUDIT/'HERBALISM_CANDIDATE_VALIDATION.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'status':report['status'],'checks':len(checks),'failed':report['failed']}))
    if report['failed']:raise SystemExit(1)

if __name__=='__main__':main()
